pub struct Solution;

impl Solution {
    pub fn roman_to_int(s: String) -> i32 {
        let val = |b: u8| -> i32 {
            match b {
                b'I' => 1,
                b'V' => 5,
                b'X' => 10,
                b'L' => 50,
                b'C' => 100,
                b'D' => 500,
                b'M' => 1000,
                _ => 0,
            }
        };

        let bytes = s.as_bytes();
        let mut total = 0;
        let mut prev = 0;

        for &b in bytes.iter().rev() {
            let current = val(b);
            if current < prev {
                total -= current;
            } else {
                total += current;
                prev = current;
            }
        }

        total
    }
}

